def beautySum(s: str) -> int:
    n = len(s)
    total = 0
    for i in range(n):
        count = [0] * 26  # Frequency of each letter
        for j in range(i, n):
            idx = ord(s[j]) - ord('a')
            count[idx] += 1
            # Find max and min frequency > 0 in this window
            max_freq = 0
            min_freq = float('inf')
            for freq in count:
                if freq > 0:
                    if freq > max_freq:
                        max_freq = freq
                    if freq < min_freq:
                        min_freq = freq
            if max_freq > min_freq:
                total += (max_freq - min_freq)
    return total
